import {BASE_PROPERTIES,BASE_FEATURES,FORMS,ELEMENTS,freshWorkspace,validateWorkspace,exactNumber,parseComposition,compositionKey,validateComposition,suggestMapping,buildDataset,predictProperty,trainingRows,uid} from './prediction-model.js';
import {readPredictionFile,toCSV} from './prediction-import.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>Number.isFinite(n)?Number(n.toPrecision(5)).toLocaleString('zh-CN',{maximumSignificantDigits:5}):'—';
const date=n=>new Date(n).toLocaleString();
const unitLabel=p=>p.name+(p.unit?' · '+p.unit:'');
const option=(value,label,selected)=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`;
const propertyOptions=(items,value)=>items.map(p=>option(p.id,unitLabel(p),value)).join('');
export function createPredictionController({host,load,persist,saveText,toast,isReady,onCount}) {
 const listeners=new AbortController();
 let workspace=freshWorkspace(),loaded=false,loading=null,libraryKey='',panel='predict',busy=false,error='',worker=null,generation=0;
 let file=null,sheet=0,headerRow=1,mapping=[],preview=null,results=[],previewOptions=null,importSettings={basis:'at',form:'',verified:false};
 let form='powder',basis='at',formula='',conditions={},draftName='',trainStatus='',lastResultInput=null;
 let queue=Promise.resolve();
 const currentRows=()=>workspace.datasets.reduce((n,d)=>n+d.rows.length,0);
 function status(){onCount?.(`${workspace.datasets.length} 个数据集 · ${currentRows()} 条记录`);}
 async function save(next){const token=generation,expectedKey=libraryKey;busy=true;error='';
  const operation=queue.then(()=>persist({libraryKey:expectedKey,state:next}));queue=operation.catch(()=>{});
  try{await operation;if(token!==generation)return;workspace=next;}catch(e){if(token===generation)error='未保存：'+e.message;throw e;}finally{if(token===generation)busy=false;}
 }
 async function ensureLoaded(){if(loaded)return;if(loading)return loading;const token=generation;
  loading=(async()=>{try{const value=await load();if(token!==generation)return;workspace=value.state?validateWorkspace(value.state):freshWorkspace();libraryKey=value.libraryKey;loaded=true;error='';}
   catch(e){if(token===generation)error=e.message;}finally{if(token===generation){loading=null;render();}}})();return loading;
 }
 function capture(){const f=host.querySelector('#prediction-form');if(f){formula=f.elements.formula.value;form=f.elements.form.value;basis=f.elements.basis.value;conditions={};for(const spec of workspace.features){const el=f.elements['feature:'+spec.id];if(el&&el.value.trim())conditions[spec.id]=spec.type==='number'?exactNumber(el.value):el.value.trim();}}}
 function shell(content){host.innerHTML=`<div class="prediction-heading"><div><span class="prediction-kicker">AMORPHOUS POWDER</span><h2>非晶粉末性能预测</h2><p>用实验数据训练，在指定成分与条件下预测性能。</p></div><span class="prediction-local">本机计算 · 数据保存在当前文献库</span></div><nav class="prediction-tabs" aria-label="预测工具"><button data-prediction-panel="predict" aria-pressed="${panel==='predict'}">配方预测</button><button data-prediction-panel="datasets" aria-pressed="${panel==='datasets'}">数据集 <small>${workspace.datasets.length}</small></button><button data-prediction-panel="models" aria-pressed="${panel==='models'}">模型训练</button><button data-prediction-panel="properties" aria-pressed="${panel==='properties'}">性能与输入字段</button></nav><div class="prediction-feedback" role="status" ${error?'':'hidden'}>${esc(error)}</div>${content}`;status();}
 function render(){if(host.hidden)return;const importForm=host.querySelector('#prediction-import-form');if(importForm){draftName=importForm.elements.name.value;importSettings={basis:importForm.elements.basis.value,form:importForm.elements.form.value,verified:importForm.elements.verified.checked};}if(!loaded){shell(`<div class="prediction-empty"><h3>${error?'预测工作区未打开':'正在打开预测工作区…'}</h3>${error?'<button class="outline-button" data-prediction-action="retry">重新读取</button>':''}</div>`);return;}
  if(panel==='predict')shell(predictHTML());if(panel==='datasets')shell(datasetsHTML());if(panel==='models')shell(modelsHTML());if(panel==='properties')shell(propertiesHTML());
 }
 function scopeFields(){return`<label>样品形态<select name="form">${option('powder',FORMS.powder,form)}${option('core',FORMS.core,form)}</select></label><label>成分百分比<select name="basis">${option('at','原子百分比 at.%',basis)}${option('wt','质量百分比 wt.%',basis)}</select></label>`;}
 function activeModels(){return workspace.models.filter(m=>m.active&&m.form===form&&m.basis===basis);}
 function predictHTML(){const models=activeModels();const usedFeatures=new Set(models.flatMap(m=>m.encoder.specs.map(f=>f.id)));
  return`<div class="prediction-two-col"><form id="prediction-form" class="prediction-card"><div class="prediction-card-title"><h3>输入配方</h3><span>元素合计 100%</span></div><div class="prediction-grid">${scopeFields()}</div><label>合金成分式<input name="formula" value="${esc(formula)}" placeholder="例如 Fe80Si9B11" autocomplete="off" required></label><p class="prediction-help">可填写成分式，或在下方逐项添加元素和百分比。括号配比会自动展开。</p><details class="prediction-elements"><summary>按元素填写</summary><div id="prediction-element-rows">${elementRows(formula)}</div><button type="button" class="text-button" data-prediction-action="add-element">＋ 添加元素</button><button type="button" class="outline-button" data-prediction-action="apply-elements">应用到成分式</button></details><details ${usedFeatures.size?'open':''}><summary>工艺与测试条件${usedFeatures.size?' · 模型使用 '+usedFeatures.size+' 项':''}</summary><div class="prediction-grid prediction-conditions">${workspace.features.filter(f=>usedFeatures.has(f.id)).map(f=>`<label>${esc(unitLabel(f))}<input name="feature:${esc(f.id)}" value="${esc(conditions[f.id]??'')}" ${f.type==='number'?'type="number" step="any"':''} placeholder="按预测条件填写"></label>`).join('')||'<p class="prediction-help">训练模型后，会在这里显示该模型使用的条件。</p>'}</div></details><button class="primary" type="submit" ${!models.length||busy?'disabled':''}>预测性能</button>${!models.length?'<p class="prediction-help">当前形态和比例类型还没有通过验证的模型。</p><button type="button" class="text-button" data-prediction-panel="datasets">导入实验数据 →</button>':''}</form><div class="prediction-card prediction-output"><div class="prediction-card-title"><h3>性能结果</h3><button class="text-button" data-prediction-action="export-results" ${results.length?'':'disabled'}>导出结果</button></div>${results.length?`<p class="prediction-help">${esc(lastResultInput?.formula)} · ${esc(FORMS[lastResultInput?.form])} · ${lastResultInput?.basis==='at'?'at.%':'wt.%'}</p>`:'<p class="prediction-help">预测值与验证误差会逐项显示。未训练的性能保留在列表中。</p>'}<div class="prediction-result-list">${predictionResults(models)}</div><p class="prediction-help">MAE 是历史分组验证的平均绝对误差，不是单次预测的置信区间。</p></div></div>`;
 }
 function propertyResult(p,models){const r=results.find(r=>r.target===p.id),m=models.find(m=>m.target===p.id);return`<div class="prediction-result"><div><strong>${esc(p.name)}</strong><small>${esc(p.unit||'无量纲')}</small></div><div>${r?.value!==undefined?`<b>${number(r.value)}</b><small>${r.derived?'由 Tx − Tg 计算':'分组验证 MAE '+number(r.mae)}${r.stale?' · 数据已变更':''}</small>${r.warnings?.length?`<small class="prediction-warning">${esc(r.warnings.join('；'))}</small>`:''}`:`<span class="prediction-muted">${esc(r?.error||(m?'等待输入':'待训练'))}</span>`}</div></div>`;}
 function predictionResults(models){
  const available=new Set([...models.map(m=>m.target),...results.map(r=>r.target)]);
  const ready=workspace.properties.filter(p=>available.has(p.id)),pending=workspace.properties.filter(p=>!available.has(p.id));
  return (ready.map(p=>propertyResult(p,models)).join('')||'<div class="prediction-output-empty">导入实验数据并训练模型后，<br>在这里查看可预测的性能。</div>')+(pending.length?`<details class="prediction-pending"><summary>待训练的性能 · ${pending.length}</summary>${pending.map(p=>propertyResult(p,models)).join('')}</details>`:'');
 }
 function elementRows(value){let c;try{c=parseComposition(value);}catch{c={Fe:'',Si:'',B:''};}return Object.entries(c).map(([e,n])=>elementRow(e,n)).join('');}
 function elementRow(e='',n=''){return`<div class="prediction-element"><select aria-label="元素">${option('','选择元素',e)}${ELEMENTS.map(v=>option(v,v,e)).join('')}</select><input aria-label="元素百分比" type="number" min="0" max="100" step="any" value="${esc(n)}" placeholder="百分比"><span>%</span><button type="button" class="text-button" data-prediction-action="remove-element" aria-label="移除此元素">×</button></div>`;}
 function datasetsHTML(){return`<div class="prediction-actions"><label class="outline-button prediction-file-label">导入 Excel / CSV<input id="prediction-upload" type="file" accept=".xlsx,.csv,.tsv" hidden ${busy?'disabled':''}></label><button class="outline-button" data-prediction-action="template">下载数据模板</button><button class="text-button" data-prediction-action="export-workspace">导出预测工作区</button><label class="text-button prediction-file-label">恢复工作区<input id="prediction-restore" type="file" accept=".json" hidden ${busy?'disabled':''}></label></div>${file?importHTML():''}<div class="prediction-card"><h3>实验数据集</h3>${workspace.datasets.length?`<div class="prediction-table-wrap"><table><thead><tr><th>数据集</th><th>形态／比例</th><th>有效记录</th><th>覆盖性能</th><th>操作</th></tr></thead><tbody>${workspace.datasets.map(d=>`<tr><td><strong>${esc(d.name)}</strong><small>${esc(d.filename)}${d.sheetName?' · '+esc(d.sheetName):''}</small></td><td>${esc(FORMS[d.form])}<small>${d.basis==='at'?'at.%':'wt.%'}</small></td><td>${d.rows.length}<small>${d.issues.length} 行跳过 · ${d.duplicates} 行重复</small></td><td>${workspace.properties.filter(p=>d.rows.some(r=>r.targets[p.id]!==undefined)).map(p=>esc(p.name)).join('、')}</td><td><button class="text-button" data-export-dataset="${esc(d.id)}">导出</button><button class="text-button" data-remove-dataset="${esc(d.id)}" ${busy?'disabled':''}>移除…</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="prediction-empty"><h3>从你的第一份实验数据开始</h3><p>先导入文件，再核对成分、单位、样品形态和性能列。</p><p>不等式、区间、未确定元素会保留在导入报告中，不直接充当确定数值训练。</p></div>'}<p class="prediction-help">数据集导入后不会自动改动已训练模型。新增数据后请重新训练。预测结果不作为实验标签回流。</p></div>`;}
 function importHTML(){const current=file.sheets[sheet],headers=current.rows[headerRow-1]||[],table=current.rows.slice(headerRow-1);return`<section class="prediction-card"><div class="prediction-card-title"><h3>核对导入 · ${esc(file.filename)}</h3><button class="text-button" data-prediction-action="close-import">收起</button></div><form id="prediction-import-form"><div class="prediction-grid"><label>数据集名称<input name="name" value="${esc(draftName)}" required></label><label>工作表<select id="prediction-sheet">${file.sheets.map((s,i)=>option(String(i),s.name,String(sheet))).join('')}</select></label><label>表头所在行<input id="prediction-header" type="number" min="1" max="${current.rows.length}" value="${headerRow}"></label><label>比例类型<select name="basis">${option('at','原子百分比 at.%',importSettings.basis)}${option('wt','质量百分比 wt.%',importSettings.basis)}</select></label><label>样品形态<select name="form" required><option value="">请选择并核对</option>${Object.entries(FORMS).map(([k,v])=>option(k,v,importSettings.form)).join('')}</select></label></div><p class="prediction-help">列名不会证明单位和样品形态正确。块体、带材等请选择参考数据，不用于粉末／粉芯模型。空白元素单元格按该元素 0% 处理；缺失性能保持缺失。</p>${current.formulaCount?`<p class="prediction-warning">文件含 ${current.formulaCount} 个公式，读取 Excel 已保存的结果，不执行公式。请先在 Excel 中重算并核对异常值。</p>`:''}<div class="prediction-table-wrap prediction-mapping"><table><thead><tr><th>原表列名／样例</th><th>用途</th><th>对应字段</th><th>字段单位</th></tr></thead><tbody>${headers.map((h,i)=>{const m=mapping[i]||{role:'ignore',id:''},items=m.role==='target'?workspace.properties:m.role==='feature'?workspace.features:[];return`<tr><td><strong>${esc(h||'未命名列 '+(i+1))}</strong><small>${esc(table.slice(1,4).map(r=>r[i]??'').join(' / ')).slice(0,160)}</small></td><td><select data-mapping-role="${i}">${[['ignore','忽略'],['composition','成分式'],['element','元素百分比'],['feature','工艺／测试输入'],['target','实测性能'],['source','来源／DOI']].map(([k,v])=>option(k,v,m.role)).join('')}</select></td><td>${m.role==='element'?`<select data-mapping-id="${i}">${ELEMENTS.map(e=>option(e,e,m.id)).join('')}</select>`:items.length?`<select data-mapping-id="${i}">${propertyOptions(items,m.id)}</select>`:'—'}</td><td>${esc(items.find(p=>p.id===m.id)?.unit||'—')}</td></tr>`;}).join('')}</tbody></table></div><p class="prediction-help">没有对应字段？先到“性能与输入字段”新增，再回来映射。尤其注意 HV 硬度与 GPa、K 与 °C 等单位，不会自动换算。</p><label class="prediction-check"><input type="checkbox" name="verified" ${importSettings.verified?'checked':''} required>已核对比例类型、样品形态、各列单位，且性能值为实验／文献实测数据</label><button class="outline-button" type="submit" ${busy?'disabled':''}>预览可导入记录</button></form>${preview?`<div class="prediction-import-report"><strong>${preview.rows.length} 条可导入 · ${preview.issues.length} 行跳过 · ${preview.duplicates} 行重复</strong><p>${preview.qualified} 个非确定数值单元格未用作训练标签。</p>${preview.issues.length?`<details><summary>查看跳过原因</summary>${preview.issues.slice(0,40).map(i=>`<p>第 ${i.row+headerRow-1} 行：${esc(i.message)}</p>`).join('')}</details>`:''}<button class="primary" data-prediction-action="confirm-import" ${busy?'disabled':''}>确认导入数据集</button></div>`:''}</section>`;}
 function modelsHTML(){const datasets=workspace.datasets.filter(d=>d.form===form&&d.basis===basis);return`<div class="prediction-card"><h3>训练与验证</h3><p class="prediction-help">各性能分别训练本地树集成回归模型。按成分分成 5 组验证，相同配比不跨训练组与测试组；也可按来源与成分共同分组。全部预处理只使用当前训练折。</p><form id="prediction-train-form"><div class="prediction-grid">${scopeFields()}<label>验证方式<select name="validation"><option value="composition">按成分分组 · 5 折</option><option value="source">按来源与成分分组 · 5 折</option></select></label></div><fieldset><legend>训练数据集</legend>${datasets.map(d=>`<label class="prediction-check"><input name="dataset" type="checkbox" value="${esc(d.id)}" checked>${esc(d.name)} · ${d.rows.length} 条</label>`).join('')||'<p class="prediction-help">当前范围没有数据，请先导入相应形态和比例类型的实验记录。</p>'}</fieldset><fieldset><legend>预测目标</legend><div class="prediction-property-choices">${workspace.properties.map(p=>{const n=trainingRows(workspace,{datasetIds:datasets.map(d=>d.id),form,basis,target:p.id}).length;return`<label class="prediction-check"><input name="target" type="checkbox" value="${esc(p.id)}" ${n<15?'disabled':''}><span>${esc(p.name)}<small>${n} 条有效标签${n<15?' · 待补数据':''}</small></span></label>`;}).join('')}</div></fieldset><p class="prediction-help">至少 15 条有效标签和 5 组独立成分才能运行，能否使用由验证结果决定。与均值基线比较，通过后才启用预测。</p><div class="prediction-actions"><button type="submit" class="primary" ${busy||!datasets.length?'disabled':''}>训练所选性能</button>${busy&&worker?'<button type="button" class="outline-button" data-prediction-action="cancel-train">停止训练</button>':''}<span id="prediction-train-status" role="status">${esc(trainStatus)}</span></div></form></div><div class="prediction-card"><div class="prediction-card-title"><h3>模型记录</h3><small>MAE／RMSE 使用对应性能的单位</small></div>${workspace.models.length?`<div class="prediction-table-wrap"><table><thead><tr><th>性能／范围</th><th>样本／分组</th><th>MAE</th><th>RMSE</th><th>R²</th><th>均值基线 MAE</th><th>状态</th><th></th></tr></thead><tbody>${[...workspace.models].reverse().map(m=>`<tr><td>${esc(unitLabel(m.property))}<small>${esc(FORMS[m.form])} · ${m.basis==='at'?'at.%':'wt.%'} · ${date(m.createdAt)}</small></td><td>${m.metrics.n}／${m.metrics.groups}<small>${m.metrics.validation==='source'?'来源与成分分组':'成分分组'}</small></td><td>${number(m.metrics.mae)}</td><td>${number(m.metrics.rmse)}</td><td>${number(m.metrics.r2)}</td><td>${number(m.metrics.baselineMAE)}</td><td>${m.active?'已启用':m.usable?'历史版本':'未优于基线'}${m.revision!==workspace.revision?'<small class="prediction-warning">数据已变更，建议重训</small>':''}</td><td><button class="text-button" data-model-details="${esc(m.id)}">验证明细</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="prediction-empty"><p>训练完成后，这里会保留误差、验证方式和模型版本。</p></div>'}</div>`;}
 function propertiesHTML(){return`<div class="prediction-card"><h3>扩展性能与输入</h3><p class="prediction-help">新增性能后，导入对应实测数据并训练即可预测。新增输入字段后，可在导入时映射，并在训练后用于预测。</p><form id="prediction-field-form" class="prediction-grid"><label>字段用途<select name="kind"><option value="target">预测性能</option><option value="number">数值输入条件</option><option value="category">分类输入条件</option></select></label><label>名称<input name="name" required maxlength="100" placeholder="例如 氧含量"></label><label>单位<input name="unit" maxlength="40" placeholder="例如 wt.%；无量纲可留空"></label><button type="submit" class="outline-button" ${busy?'disabled':''}>新增字段</button></form></div><div class="prediction-two-col"><div class="prediction-card"><h3>性能指标 · ${workspace.properties.length}</h3><div class="prediction-field-list">${workspace.properties.map(p=>`<div><span>${esc(p.name)}</span><small>${esc(p.unit||'无量纲')}</small></div>`).join('')}</div><p class="prediction-help">dc 保留作参考形态的形成能力指标，不等同于粉末粒径；B 在力学指标中指体积模量。</p></div><div class="prediction-card"><h3>工艺与测试输入 · ${workspace.features.length}</h3><div class="prediction-field-list">${workspace.features.map(f=>`<div><span>${esc(f.name)}</span><small>${esc(f.unit|| (f.type==='category'?'分类':'无量纲'))}</small></div>`).join('')}</div></div></div>`;}
 function resetMapping(){mapping=(file.sheets[sheet].rows[headerRow-1]||[]).map(h=>suggestMapping(h,workspace.properties,workspace.features));preview=null;}
 async function runTraining(data){
  if(busy)return;const datasetIds=data.getAll('dataset'),targets=data.getAll('target');if(!targets.length)throw Error('请勾选要训练的性能。');if(!datasetIds.length)throw Error('请选择训练数据集。');
  const token=generation,snapshot=structuredClone(workspace);busy=true;trainStatus='准备训练…';error='';render();let completed=0;
  try{for(const target of targets){if(token!==generation)return;trainStatus=`正在训练 ${workspace.properties.find(p=>p.id===target)?.name}（${completed+1}/${targets.length}）`;worker=new Worker(new URL('./prediction-worker.js',import.meta.url),{type:'module'});render();
    const model=await new Promise((resolve,reject)=>{worker.onmessage=e=>e.data.error?reject(Error(e.data.error)):resolve(e.data.model);worker.onerror=e=>reject(Error(e.message||'训练失败。'));worker.cancel=()=>reject(Error('训练已停止，已完成的模型保留。'));worker.postMessage({workspace:snapshot,options:{target,datasetIds,form,basis,validation:data.get('validation')}});});
    worker.terminate();worker=null;if(token!==generation)return;
    const next=structuredClone(workspace);if(model.usable)for(const m of next.models)if(m.target===target&&m.form===form&&m.basis===basis)m.active=false;
    next.models.push({...model,active:model.usable});if(next.models.length>150)next.models=next.models.slice(-150);await save(next);busy=true;completed++;
   }trainStatus=`已完成 ${completed} 项训练。查看下方验证结果。`;
  }finally{worker?.terminate();worker=null;if(token===generation){busy=false;render();}}
 }
 function prediction(data){capture();const composition=parseComposition(data.get('formula')),models=activeModels();results=[];
  for(const m of models){try{const r=predictProperty(m,{composition,features:conditions});results.push({target:m.target,...r,stale:m.revision!==workspace.revision,modelId:m.id});}catch(e){results.push({target:m.target,error:e.message});}}
  if(!results.some(r=>r.target==='deltaTx'&&r.value!==undefined)){const tg=results.find(r=>r.target==='Tg'),tx=results.find(r=>r.target==='Tx');if(tg?.value!==undefined&&tx?.value!==undefined){results=results.filter(r=>r.target!=='deltaTx');results.push({target:'deltaTx',value:tx.value-tg.value,derived:true,warnings:[...(tg.warnings||[]),...(tx.warnings||[])],stale:tg.stale||tx.stale});}}
  lastResultInput={formula:compositionKey(composition),composition,form,basis,conditions:{...conditions}};render();
 }
 host.addEventListener('submit',async event=>{event.preventDefault();if(!loaded||busy)return;try{const data=new FormData(event.target);error='';
  if(event.target.id==='prediction-form')prediction(data);
  if(event.target.id==='prediction-field-form'){
   const name=String(data.get('name')).trim(),unit=String(data.get('unit')).trim(),kind=data.get('kind'),next=structuredClone(workspace),items=kind==='target'?next.properties:next.features;
   if(!name||items.some(f=>f.name===name))throw Error('名称为空或已存在。');items.push({id:'custom_'+uid().replaceAll('-',''),name,unit,aliases:[name],...(kind==='target'?{}:{type:kind})});await save(next);preview=null;render();toast('字段已新增，可在导入时映射。');
  }
  if(event.target.id==='prediction-import-form'){
   draftName=String(data.get('name'));previewOptions={name:draftName,basis:data.get('basis'),form:data.get('form')};
   preview=buildDataset({...previewOptions,table:file.sheets[sheet].rows.slice(headerRow-1),mapping,features:workspace.features,properties:workspace.properties,filename:file.filename,sheetName:file.sheets[sheet].name});render();
  }
  if(event.target.id==='prediction-train-form')await runTraining(data);
 }catch(e){error=error.startsWith('未保存')?error:e.message;render();toast(e.message,true);}},{signal:listeners.signal});
 host.addEventListener('change',async event=>{const el=event.target;try{
  if(el.id==='prediction-upload'){const selected=el.files[0];if(!selected)return;const incoming=await readPredictionFile(selected);host.querySelector('#prediction-import-form')?.remove();file=incoming;importSettings={basis:'at',form:'',verified:false};sheet=0;headerRow=1;draftName=selected.name.replace(/\.[^.]+$/,'');resetMapping();render();}
  if(el.id==='prediction-restore'){const selected=el.files[0];if(!selected)return;if(selected.size>30*1024*1024)throw Error('工作区文件超过 30 MB。');const next=validateWorkspace(JSON.parse(await selected.text()));if(!confirm('恢复将替换当前预测工作区的数据集与模型。请先导出备份。继续恢复？'))return;await save(next);file=null;results=[];render();}
  if(el.id==='prediction-sheet'||el.id==='prediction-header'){host.querySelector('[name="verified"]').checked=false;draftName=host.querySelector('#prediction-import-form [name="name"]')?.value||draftName;if(el.id==='prediction-sheet'){sheet=Number(el.value);headerRow=1;}else headerRow=Math.max(1,Math.min(file.sheets[sheet].rows.length,Number(el.value)||1));resetMapping();render();}
  if(el.dataset.mappingRole!==undefined){host.querySelector('[name="verified"]').checked=false;const i=Number(el.dataset.mappingRole),role=el.value;mapping[i]={role,id:role==='target'?workspace.properties[0].id:role==='feature'?workspace.features[0].id:role==='element'?'Fe':''};preview=null;draftName=host.querySelector('#prediction-import-form [name="name"]')?.value||draftName;render();}
  if(el.dataset.mappingId!==undefined){host.querySelector('[name="verified"]').checked=false;mapping[Number(el.dataset.mappingId)].id=el.value;preview=null;render();}
  if(el.closest('#prediction-import-form')&&['name','form','basis','verified'].includes(el.name)){preview=null;const report=host.querySelector('.prediction-import-report');report?.remove();}
  if(el.closest('#prediction-form')){capture();if(['basis','form'].includes(el.name)){results=[];render();}}
  if(el.closest('#prediction-train-form')&&['basis','form'].includes(el.name)){form=el.closest('form').elements.form.value;basis=el.closest('form').elements.basis.value;results=[];render();}
 }catch(e){error=error.startsWith('未保存')?error:e.message;render();toast(e.message,true);}},{signal:listeners.signal});
 host.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;try{
  if(button.dataset.predictionPanel){if(busy){toast('请等待当前操作完成，或停止训练。');return;}capture();panel=button.dataset.predictionPanel;render();return;}
  const action=button.dataset.predictionAction;
  if(action==='cancel-train'){worker?.cancel();worker?.terminate();return;}
  if(busy)return;
  if(action==='retry'){error='';await ensureLoaded();}
  if(action==='add-element')host.querySelector('#prediction-element-rows').insertAdjacentHTML('beforeend',elementRow());
  if(action==='remove-element')button.closest('.prediction-element').remove();
  if(action==='apply-elements'){const c={};for(const row of host.querySelectorAll('.prediction-element')){const e=row.querySelector('select').value,n=exactNumber(row.querySelector('input').value);if(!e||n===null)throw Error('每一行都需要元素和百分比。');if(c[e]!==undefined)throw Error('同一个元素不能重复。');c[e]=n;}formula=compositionKey(validateComposition(c));host.querySelector('[name="formula"]').value=formula;}
  if(action==='close-import'){file=null;preview=null;render();}
  if(action==='confirm-import'){if(!preview)return;const next=structuredClone(workspace);next.datasets.push(preview);next.revision++;await save(next);file=null;preview=null;results=[];render();toast('实验数据已导入，可到模型训练中选择性能。');}
  if(action==='template'){const columns=['composition',...workspace.features.map(f=>f.id+(f.unit?'('+f.unit+')':'')),...workspace.properties.map(p=>p.id+(p.unit?'('+p.unit+')':'')),'DOI'];await saveText(toCSV([columns,['Fe80Si9B11',...columns.slice(1).map(()=>'')]]),'materia-powder-template.csv','csv');}
  if(action==='export-workspace')await saveText(JSON.stringify(workspace,null,2),'materia-prediction-workspace.json','json');
  if(action==='export-results')await saveText(toCSV([['成分','形态','百分比类型','输入条件','性能','预测值','单位','分组验证MAE','状态／提示','模型ID','数值类型'],...results.map(r=>{const p=workspace.properties.find(p=>p.id===r.target);return[lastResultInput.formula,FORMS[lastResultInput.form],lastResultInput.basis,JSON.stringify(lastResultInput.conditions),p.name,r.value??'',p.unit,r.mae??'',r.error||[r.stale?'数据已变更':'',...(r.warnings||[])].filter(Boolean).join('；'),r.modelId||'',r.derived?'由预测值计算':'模型预测，非实测'];})]),'materia-predictions.csv','csv');
  if(button.dataset.removeDataset){const d=workspace.datasets.find(d=>d.id===button.dataset.removeDataset);if(!confirm('移除数据集“'+d.name+'”？依赖此数据集的模型会停用。'))return;const next=structuredClone(workspace);next.datasets=next.datasets.filter(d=>d.id!==button.dataset.removeDataset);for(const m of next.models)if(m.datasetIds.includes(button.dataset.removeDataset))m.active=false;next.revision++;await save(next);results=[];render();}
  if(button.dataset.exportDataset){const d=workspace.datasets.find(d=>d.id===button.dataset.exportDataset),cols=[...workspace.features.map(f=>f.id),...workspace.properties.map(p=>p.id)];await saveText(toCSV([['composition',...cols,'DOI'],...d.rows.map(r=>[compositionKey(r.composition),...workspace.features.map(f=>r.features[f.id]??''),...workspace.properties.map(p=>r.targets[p.id]??r.original[p.id]??''),r.source])]),'materia-dataset.csv','csv');}
  if(button.dataset.modelDetails){const m=workspace.models.find(m=>m.id===button.dataset.modelDetails);await saveText(toCSV([['实测值','折外预测值','残差','性能','单位','验证方式'],...m.validationPoints.map(p=>[p.actual,p.predicted,p.actual-p.predicted,m.property.name,m.property.unit,m.metrics.validation])]),'materia-model-validation.csv','csv');}
 }catch(e){error=error.startsWith('未保存')?error:e.message;render();toast(e.message,true);}},{signal:listeners.signal});
 return{
  show(){if(!isReady())return;ensureLoaded();if(loaded&&!host.children.length)render();status();},
  async flush(){if(worker)throw Error('请等待性能模型训练完成，或先停止训练。');await queue;if(error.startsWith('未保存'))throw Error(error);},
  reset(){generation++;worker?.cancel();worker?.terminate();worker=null;loaded=false;loading=null;workspace=freshWorkspace();file=null;preview=null;results=[];conditions={};formula='';busy=false;error='';trainStatus='';host.replaceChildren();},
  dispose(){generation++;listeners.abort();worker?.cancel();worker?.terminate();worker=null;host.replaceChildren();},
 };
}
